创建型模式 简单工厂模式 public interface IProduct { void Use(); // 所有产品都会提供 Use() 方法 } public class ProductA : IProduct { public void Use() { Console.WriteLine(&#34;使用产品 A 的功能...&#34;); } } public class ProductB : IProduct { public void Use() { Console.WriteLine(&#34;使用产品 B 的功能...&#34;); } } public static class SimpleFactory { public static IProduct CreateProduct(string type) { switch (type) { case &#34;A&#34;: return new ProductA(); case &#34;B&#34;: return new ProductB(); default: throw new ArgumentException($&#34;未知产品类型：{type}&#34;); } } } 测试代码 class Program { static void Main(string[] args) { // 客户端决定需要哪个类型的产品，或者可以由配置文件/用户输入等决定 IProduct product1 = SimpleFactory.CreateProduct(&#34;A&#34;); product1.Use(); // 输出：使用产品 A 的功能... IProduct product2 = SimpleFactory.CreateProduct(&#34;B&#34;); product2.Use(); // 输出：使用产品 B 的功能... } } 工厂方法模式 //我们以“日志记录器（Logger）”为例，实现两种不同的日志输出方式：Console 日志与 File 日志 public interface ILogger { void Log(string message); } public class ConsoleLogger : ILogger { public void Log(string message) { Console.WriteLine($&#34;[Console Logger] {message}&#34;); } } public class FileLogger : ILogger { public void Log(string message) { // 简化实现，实际要考虑IO处理、文件路径等 File.WriteAllText(@&#34;&#34;,$&#34;{message}&#34;); } } //定义抽象工厂 public abstract class LoggerCreator { // 工厂方法 public abstract ILogger FactoryMethod(); // 提供公共逻辑，这里演示一个示例 public void WriteLog(string message) { // 通过工厂方法获得具体日志类 ILogger logger = FactoryMethod(); // 写入日志 logger.Log(message); } } //定义具体工厂 public class ConsoleLoggerCreator : LoggerCreator { public override ILogger FactoryMethod() { return new ConsoleLogger(); } } public class FileLoggerCreator : LoggerCreator { public override ILogger FactoryMethod() { return new FileLogger(); } } 测试代码 class Program { static void Main(string[] args) { // 可能来自配置或运行时判断 LoggerCreator creator; // 假设在这里我们需要一个控制台日志 creator = new ConsoleLoggerCreator(); creator.WriteLog(&#34;这是控制台日志内容&#34;); // 假设在这里我们需要一个文件日志 creator = new FileLoggerCreator(); creator.WriteLog(&#34;这是文件日志内容&#34;); } } 原型模式 public interface IPrototype { IPrototype Clone(); } //这其中包含一个Clone()方法，所有实现该接口的类都必须提供克隆自身的逻辑 //浅拷贝 public class ConcretePrototype : IPrototype { public string Name { get; set; } public List&lt;string&gt; Tags { get; set; } // 浅拷贝：直接使用 MemberwiseClone() public IPrototype Clone() { return this.MemberwiseClone() as IPrototype; } public override string ToString() { return $&#34;ConcretePrototype [Name={Name}, Tags={string.Join(&#34;,&#34;, Tags)}]&#34;; } } //深拷贝 public class DeepPrototype : IPrototype { public string Name { get; set; } public List&lt;string&gt; Tags { get; set; } // 深拷贝：自己动手复制复杂引用类型的内容 public IPrototype Clone() { // 先浅拷贝 DeepPrototype copy = this.MemberwiseClone() as DeepPrototype; // 对引用类型字段进行单独拷贝 copy.Tags = new List&lt;string&gt;(this.Tags); return copy; } public override string ToString() { return $&#34;DeepPrototype [Name={Name}, Tags={string.Join(&#34;,&#34;, Tags)}]&#34;; } } 测试代码 class Program { static void Main(string[] args) { // ========== 浅拷贝示例 ========== ConcretePrototype prototypeA = new ConcretePrototype { Name = &#34;Alpha&#34;, Tags = new List&lt;string&gt; { &#34;Tag1&#34;, &#34;Tag2&#34; } }; Console.WriteLine(&#34;原对象 prototypeA: &#34; + prototypeA); // 克隆 var cloneA = prototypeA.Clone() as ConcretePrototype; Console.WriteLine(&#34;克隆对象 cloneA: &#34; + cloneA); // 修改克隆对象的引用类型字段 cloneA.Tags[0] = &#34;Tag999&#34;; Console.WriteLine(&#34;
修改 cloneA 的第一项后:&#34;); Console.WriteLine(&#34;原对象 prototypeA: &#34; + prototypeA); // &#34;Tag999&#34; 出现 Console.WriteLine(&#34;克隆对象 cloneA: &#34; + cloneA); // ========== 深拷贝示例 ========== DeepPrototype prototypeB = new DeepPrototype { Name = &#34;Bravo&#34;, Tags = new List&lt;string&gt; { &#34;TagX&#34;, &#34;TagY&#34; } }; Console.WriteLine(&#34;
原对象 prototypeB: &#34; + prototypeB); // 克隆 var cloneB = prototypeB.Clone() as DeepPrototype; Console.WriteLine(&#34;克隆对象 cloneB: &#34; + cloneB); // 修改克隆对象的引用类型字段 cloneB.Tags[0] = &#34;Tag999&#34;; Console.WriteLine(&#34;
修改 cloneB 的第一项后:&#34;); Console.WriteLine(&#34;原对象 prototypeB: &#34; + prototypeB); // 仍然是 &#34;TagX&#34; Console.WriteLine(&#34;克隆对象 cloneB: &#34; + cloneB); // 暂停 Console.ReadKey(); } } 使用上感觉就是用一种隔了层纱的方式来用了指针。 建造者模式 //产品类 public class Computer { public string CPU { get; set; } public int Memory { get; set; } public int Storage { get; set; } public string GPU { get; set; } public override string ToString() { return $&#34;Computer: CPU={CPU}, Memory={Memory}GB, Storage={Storage}GB, GPU={GPU}&#34;; } } //抽象建造者 public interface IComputerBuilder { //定义了建造步骤 void BuildCPU(); void BuildMemory(); void BuildStorage(); void BuildGPU(); //最后返回最终构造好的产品对象 Computer GetComputer(); } //具体建造者 public class GamingComputerBuilder : IComputerBuilder { private Computer _computer = new Computer(); public void BuildCPU() { _computer.CPU = &#34;Intel Core i9&#34;; } public void BuildMemory() { _computer.Memory = 32; // 32 GB } public void BuildStorage() { _computer.Storage = 2000; // 2 TB } public void BuildGPU() { _computer.GPU = &#34;NVIDIA GeForce RTX 4090&#34;; } public Computer GetComputer() { return _computer; } } //办公电脑建造者 public class OfficeComputerBuilder : IComputerBuilder { private Computer _computer = new Computer(); public void BuildCPU() { _computer.CPU = &#34;Intel Core i5&#34;; } public void BuildMemory() { _computer.Memory = 16; // 16 GB } public void BuildStorage() { _computer.Storage = 512; // 512 GB } public void BuildGPU() { _computer.GPU = &#34;Integrated Graphics&#34;; } public Computer GetComputer() { return _computer; } } //指挥者 public class ComputerDirector { public void Construct(IComputerBuilder builder) { builder.BuildCPU(); builder.BuildMemory(); builder.BuildStorage(); builder.BuildGPU(); } } //电脑指挥者里只有一个构建方法，它知道构建流程，依次调用CPU、内存、存储、GPU 的建造。 //在更复杂的场景里，你也可以在指挥者里灵活地对建造步骤进行顺序/配置上的调整。 //有时也可以不使用 Director，而是让客户端自己一步步调用建造者的方法——这取决于你是否需要一个统一封装的“指挥过程”。 测试代码 class Program { static void Main(string[] args) { ComputerDirector director = new ComputerDirector(); // ========== 生产一台游戏电脑 ========== IComputerBuilder gamingBuilder = new GamingComputerBuilder(); director.Construct(gamingBuilder); Computer gamingComputer = gamingBuilder.GetComputer(); Console.WriteLine(&#34;Gaming Computer Built:&#34;); Console.WriteLine(gamingComputer); // ========== 生产一台办公电脑 ========== IComputerBuilder officeBuilder = new OfficeComputerBuilder(); director.Construct(officeBuilder); Computer officeComputer = officeBuilder.GetComputer(); Console.WriteLine(&#34;
Office Computer Built:&#34;); Console.WriteLine(officeComputer); Console.ReadKey(); } } 输出示例 Gaming Computer Built: Computer: CPU=Intel Core i9, Memory=32GB, Storage=2000GB, GPU=NVIDIA GeForce RTX 4090 Office Computer Built: Computer: CPU=Intel Core i5, Memory=16GB, Storage=512GB, GPU=Integrated Graphics 设计模式的优缺点 优点 封装复杂构造：将复杂对象的创建过程分步骤封装到建造者里面，客户端不必关注各个零件如何装配。 更易扩展：需要变更或增加产品的组成，可以新建一个 ConcreteBuilder 或调整指挥者的构建流程。 符合单一职责：Builder 只负责如何一步步创建对象，Director 负责指挥建造流程，Product 对象则只是数据结构。 缺点 类数量增加：对于每种产品变体，都需要一个对应的 ConcreteBuilder。 不适合变化过于频繁的场景：如果对象结构本身经常变动，Builder 也要不断调整。 何时考虑使用建造者模式 需要创建的对象内部结构复杂，且存在多种组合或变体。 需要将复杂的构造过程与对象本身的业务逻辑分离，使得构造过程可以被单独管理或扩展。 希望通过不同的建造者来创建“同一类对象”的不同版本（如游戏版、办公版、低配版、高配版等）。

