修改 cloneB 的第一项后:&#34;); Console.WriteLine(&#34;原对象 prototypeB: &#34; + prototypeB); // 仍然是 &#34;TagX&#34; Console.WriteLine(&#34;克隆对象 cloneB: &#34; + cloneB); // 暂停 Console.ReadKey(); } } 使用上感觉就是用一种隔了层纱的方式来用了指针。 建造者模式 //产品类 public class Computer { public string CPU { get; set; } public int Memory { get; set; } public int Storage { get; set; } public string GPU { get; set; } public override string ToString() { return $&#34;Computer: CPU={CPU}, Memory={Memory}GB, Storage={Storage}GB, GPU={GPU}&#34;; } } //抽象建造者 public interface IComputerBuilder { //定义了建造步骤 void BuildCPU(); void BuildMemory(); void BuildStorage(); void BuildGPU(); //最后返回最终构造好的产品对象 Computer GetComputer(); } //具体建造者 public class GamingComputerBuilder : IComputerBuilder { private Computer _computer = new Computer(); public void BuildCPU() { _computer.CPU = &#34;Intel Core i9&#34;; } public void BuildMemory() { _computer.Memory = 32; // 32 GB } public void BuildStorage() { _computer.Storage = 2000; // 2 TB } public void BuildGPU() { _computer.GPU = &#34;NVIDIA GeForce RTX 4090&#34;; } public Computer GetComputer() { return _computer; } } //办公电脑建造者 public class OfficeComputerBuilder : IComputerBuilder { private Computer _computer = new Computer(); public void BuildCPU() { _computer.CPU = &#34;Intel Core i5&#34;; } public void BuildMemory() { _computer.Memory = 16; // 16 GB } public void BuildStorage() { _computer.Storage = 512; // 512 GB } public void BuildGPU() { _computer.GPU = &#34;Integrated Graphics&#34;; } public Computer GetComputer() { return _computer; } } //指挥者 public class ComputerDirector { public void Construct(IComputerBuilder builder) { builder.BuildCPU(); builder.BuildMemory(); builder.BuildStorage(); builder.BuildGPU(); } } //电脑指挥者里只有一个构建方法，它知道构建流程，依次调用CPU、内存、存储、GPU 的建造。 //在更复杂的场景里，你也可以在指挥者里灵活地对建造步骤进行顺序/配置上的调整。 //有时也可以不使用 Director，而是让客户端自己一步步调用建造者的方法——这取决于你是否需要一个统一封装的“指挥过程”。 测试代码 class Program { static void Main(string[] args) { ComputerDirector director = new ComputerDirector(); // =======